const input = $input.first().json;
const message = input.message ?? input;
const chat = message.chat ?? {};
const from = message.from ?? {};

const chatId = String(chat.id ?? '');
const messageId = String(message.message_id ?? '');
const text = String(message.text ?? '').trim();
const isPrivate = String(chat.type ?? '') === 'private';
const fromBot = from.is_bot === true;

let messageType = 'other';
if (text) {
  messageType = 'text';
} else if (message.voice || message.audio) {
  messageType = 'audio';
} else if (message.photo) {
  messageType = 'image';
} else if (message.video) {
  messageType = 'video';
} else if (message.document) {
  messageType = 'document';
} else if (message.sticker) {
  messageType = 'sticker';
}

const TIME_ZONE = 'America/Bahia';
const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: TIME_ZONE,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hourCycle: 'h23',
});

const parts = Object.fromEntries(
  formatter.formatToParts(new Date())
    .filter(part => part.type !== 'literal')
    .map(part => [part.type, part.value])
);

const localDate = `${parts.year}-${parts.month}-${parts.day}`;
const localHour = Number(parts.hour);
const localMinute = Number(parts.minute);

const easterSunday = year => {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
};

const formatBahiaDate = date => {
  const p = Object.fromEntries(
    formatter.formatToParts(date)
      .filter(part => part.type !== 'literal')
      .map(part => [part.type, part.value])
  );
  return `${p.year}-${p.month}-${p.day}`;
};

const addDays = (date, days) => new Date(date.getTime() + days * 86400000);
const year = Number(parts.year);
const easter = easterSunday(year);
const goodFriday = formatBahiaDate(addDays(easter, -2));
const corpusChristi = formatBahiaDate(addDays(easter, 60));

const holidays = new Set([
  `${parts.year}-01-01`,
  goodFriday,
  `${parts.year}-04-21`,
  `${parts.year}-05-01`,
  corpusChristi,
  `${parts.year}-06-24`,
  `${parts.year}-07-02`,
  `${parts.year}-09-07`,
  `${parts.year}-10-12`,
  `${parts.year}-11-02`,
  `${parts.year}-11-15`,
  `${parts.year}-11-20`,
  `${parts.year}-12-08`,
  `${parts.year}-12-25`,
]);

const isHoliday = holidays.has(localDate);
const isWeekend = parts.weekday === 'Sat' || parts.weekday === 'Sun';
const isProgramWindow = !isWeekend && !isHoliday && localHour === 21;

const state = $getWorkflowStaticData('global');
state.customerSessions ??= {};
state.processedMessages ??= {};

const dedupKey = `telegram:${chatId}:${messageId}`;
const nowMs = Date.now();
const DEDUP_TTL_MS = 15 * 60 * 1000;

for (const [id, timestamp] of Object.entries(state.processedMessages)) {
  if (typeof timestamp !== 'number' || nowMs - timestamp > DEDUP_TTL_MS) {
    delete state.processedMessages[id];
  }
}

const duplicated = Boolean(messageId && state.processedMessages[dedupKey]);
if (chatId && messageId && !duplicated) {
  state.processedMessages[dedupKey] = nowMs;
}

const shouldRespond =
  !duplicated &&
  !fromBot &&
  isPrivate &&
  messageType === 'text' &&
  text.length > 0 &&
  !isProgramWindow;

const sessionKey = `telegram:${chatId}`;
const SESSION_MINUTES = 30;
const ttl = SESSION_MINUTES * 60 * 1000;
const current = state.customerSessions[sessionKey];
const hasActiveSession = Boolean(
  current?.lastSeen && Date.now() - current.lastSeen < ttl
);
const firstInteraction = !hasActiveSession;
const history = Array.isArray(current?.history)
  ? current.history.slice(-10)
  : [];

if (shouldRespond) {
  state.customerSessions[sessionKey] = { lastSeen: Date.now(), history };
}

return [{ json: {
  shouldRespond,
  reason: duplicated
    ? 'duplicate'
    : fromBot
      ? 'from_bot'
      : !isPrivate
        ? 'non_private'
        : messageType !== 'text'
          ? 'non_text'
          : isProgramWindow
            ? 'live_program'
            : 'text_allowed',
  channel: 'telegram',
  chatId,
  messageId,
  messageType,
  text,
  firstInteraction,
  history,
  isHoliday,
  isWeekend,
  isProgramWindow,
  localDate,
  localTime: String(localHour).padStart(2, '0') + ':' + String(localMinute).padStart(2, '0'),
} }];

const response = $input.first().json;
const context = $('Preparar atendimento').item.json;
const silent = response.assistant?.silent === true;

let answer = String(response.assistant?.answer ?? '').trim();
if (!answer && !silent) {
  return [];
}

answer = answer
  .replace(
    'Preferencialmente, envie pelo Telegram, que é o canal oficial do Momento do Presidiário.',
    'Você pode enviar o áudio por aqui mesmo, pelo Telegram, que é o canal oficial do Momento do Presidiário.'
  )
  .replace(
    'Continuamos recebendo os áudios por lá normalmente.',
    'Continuamos recebendo os áudios por aqui normalmente.'
  )
  .replace(
    'Este WhatsApp também recebe os áudios quando o envio por aqui for anunciado.',
    'O WhatsApp também recebe os áudios quando o recebimento por lá for anunciado.'
  );

const state = $getWorkflowStaticData('global');
state.customerSessions ??= {};
const sessionKey = `telegram:${context.chatId}`;
const current = state.customerSessions[sessionKey] ?? { history: [] };
const history = Array.isArray(current.history) ? current.history : [];

history.push({
  role: 'user',
  text: String(context.text).slice(0, 2000),
});

if (!silent && answer) {
  history.push({
    role: 'assistant',
    text: answer.slice(0, 2000),
  });
}

state.customerSessions[sessionKey] = {
  lastSeen: Date.now(),
  history: history.slice(-10),
};

if (silent || !answer) {
  return [];
}

return [{ json: { chatId: context.chatId, text: answer } }];

const input = $input.first().json;
const raw = String(input.text ?? '').replace(/\s*\n+\s*/g, '\n').trim();
if (!raw) {
  return [];
}
const limit = 3500;
const text = raw.length > limit
  ? raw.slice(0, limit - 80).trimEnd() + '…\n\nResposta limitada para envio seguro pelo Telegram.'
  : raw;
return [{ json: { chatId: input.chatId, text } }];
